public ClaimResult claim(String requestId, String claimSecret) {
  ConnectRequest request = repo.findByRequestIdForUpdate(requestId).orElse(REJECTED);
  if(!secretMatches(claimSecret, request.getClaimSecretHash())) return REJECTED;
  if(request.isExpired(now)) return REJECTED;
  return switch(request.getStatus()) {
    case APPROVED -> mint(request);
    case PENDING -> PENDING; default -> REJECTED;
  };
}

