@Transactional
public void acceptInvitationAndGrantRole(String invitationToken, User acceptingUser) {
  TeamInvitation inv = invitationRepository.findByInvitationToken(invitationToken).orElseThrow(NOT_FOUND);
  if(inv.getStatus()!=PENDING) throw ALREADY_PROCESSED;
  if(inv.isExpired()) { inv.setStatus(EXPIRED); invitationRepository.save(inv); throw EXPIRED; }
  TeamMembership membership = new TeamMembership(inv.getTeam(), acceptingUser);
  membershipRepository.save(membership);
  inv.setStatus(ACCEPTED); inv.setInviteeUser(acceptingUser); invitationRepository.save(inv);
}

